#include <stdio.h>

/* 8 位机器数对照：原码 / 反码 / 补码 / 移码（excess-128） */
static void dump(int v) {
    unsigned char bu;
    char yuan[4], fan[4];

    if (v >= 0) {
        bu = (unsigned char)v;
        snprintf(yuan, sizeof yuan, "%02X", (unsigned)bu);
        snprintf(fan, sizeof fan, "%02X", (unsigned)bu);
    } else if (v == -128) {
        bu = 0x80;                 /* 补码里 -128 就是 80，原码无法表示它 */
        snprintf(yuan, sizeof yuan, "--");
        snprintf(fan, sizeof fan, "--");
    } else {
        int m = -v;
        bu = (unsigned char)(256 + v);
        snprintf(yuan, sizeof yuan, "%02X", (unsigned)(0x80 | m));
        snprintf(fan, sizeof fan, "%02X", (unsigned)(0x80 | ((~m) & 0x7F)));
    }
    printf("  %6d     %s      %s    %02X      %02X\n",
           v, yuan, fan, (unsigned)bu, (unsigned)(bu ^ 0x80));
}

int main(void) {
    int vals[] = {0, 1, 5, 127, -1, -5, -127, -128};
    unsigned i;
    printf("=== 8-bit machine number representations ===\n");
    printf("   value   original   ones    twos    biased\n");
    for (i = 0; i < sizeof vals / sizeof vals[0]; i++) dump(vals[i]);
    printf("\nnotes:\n");
    printf("  original and ones-complement have TWO zeros (00 and 80)\n");
    printf("  twos-complement has exactly ONE zero; 80 means -128, NOT negative zero\n");
    printf("  ones-complement of -127 is 80 -> that is the negative zero artifact\n");
    printf("  biased code = twos-complement with the sign bit flipped\n");
    printf("  twos range -128..127: one more negative than positive\n");
    return 0;
}
